                 return Json(new { success = true });
             }
             catch (Exception ex)
             {
                 System.Diagnostics.Debug.WriteLine($"Error marking notification as read: {ex.Message}");
                 return Json(new { success = false, message = "Error updating notification" });
             }
         }

