        Assert.Equal("Index", redirect.ActionName);
    }

    [Fact]
    public void Edit_Post_InvalidExtension_ReturnsViewWithError()
    {
        var course = SeedCourse();
        _context.Entry(course).State = Microsoft.EntityFrameworkCore.EntityState.Detached;

        var editCourse = new Course
        {
            CourseID = course.CourseID,
            Title = "Updated",
            Credits = 3,
            DepartmentID = course.DepartmentID
        };
        var mockFile = CreateMockFormFile("malware.pdf", 1024);

        var result = _controller.Edit(editCourse, mockFile) as ViewResult;

        Assert.NotNull(result);
        Assert.True(_controller.ModelState.ContainsKey("teachingMaterialImage"));
    }

    #endregion

    #region Delete GET

    [Fact]
    public void Delete_Get_NullId_ReturnsBadRequest()
    {
        var result = _controller.Delete(null);

        var statusResult = Assert.IsType<StatusCodeResult>(result);
        Assert.Equal(400, statusResult.StatusCode);
    }

    [Fact]
    public void Delete_Get_ValidId_ReturnsViewWithCourse()
    {
        var course = SeedCourse();

        var result = _controller.Delete(course.CourseID) as ViewResult;

        Assert.NotNull(result);
        var model = Assert.IsType<Course>(result.Model);
        Assert.Equal(course.CourseID, model.CourseID);
    }

    #endregion

    #region DeleteConfirmed

    [Fact]
    public void DeleteConfirmed_ValidId_RemovesCourseAndRedirects()
    {
        var course = SeedCourse();

        var result = _controller.DeleteConfirmed(course.CourseID);

        var redirect = Assert.IsType<RedirectToActionResult>(result);
        Assert.Equal("Index", redirect.ActionName);
        Assert.Empty(_context.Courses);
    }

    #endregion

    private static IFormFile CreateMockFormFile(string fileName, long length)
    {
        var mock = new Mock<IFormFile>();
        var content = new byte[Math.Min(length, 1024)];
        var stream = new MemoryStream(content);
        mock.Setup(f => f.FileName).Returns(fileName);
        mock.Setup(f => f.Length).Returns(length);
        mock.Setup(f => f.OpenReadStream()).Returns(stream);
        mock.Setup(f => f.CopyTo(It.IsAny<Stream>())).Callback<Stream>(s => stream.CopyTo(s));
        return mock.Object;
    }
}

