        _controller = new NotificationsController(_context);
        TestHelper.SetupControllerContext(_controller);
        // Drain any leftover notifications from other tests
        DrainNotifications();
    }

    public void Dispose()
    {
        DrainNotifications();
        _controller.Dispose();
        _context.Dispose();
    }

    private void DrainNotifications()
    {
        using var svc = new NotificationService();
        while (svc.ReceiveNotification() != null) { }
    }

    [Fact]
    public void Index_ReturnsView()
    {
        var result = _controller.Index();

        Assert.IsType<ViewResult>(result);
    }

    [Fact]
    public void GetNotifications_NoNotifications_ReturnsEmptyList()
    {
        var result = _controller.GetNotifications();

        Assert.NotNull(result);
        var value = result.Value;
        Assert.NotNull(value);
        var successProp = value.GetType().GetProperty("success");
        Assert.True((bool)successProp!.GetValue(value)!);
        var countProp = value.GetType().GetProperty("count");
        Assert.Equal(0, (int)countProp!.GetValue(value)!);
    }

    [Fact]
    public void GetNotifications_WithNotifications_ReturnsNotifications()
    {
        // Enqueue some notifications
        using var svc = new NotificationService();
        svc.SendNotification("Student", "1", "John", EntityOperation.CREATE, "Admin");
        svc.SendNotification("Course", "2", "Math", EntityOperation.UPDATE, "Admin");

        var result = _controller.GetNotifications();

        var value = result.Value!;
        var countProp = value.GetType().GetProperty("count");
        var count = (int)countProp!.GetValue(value)!;
        Assert.True(count >= 2);
    }

    [Fact]
