using ContosoUniversity.Models;
using ContosoUniversity.Services;

namespace ContosoUniversity.Tests.Services;

public class NotificationServiceTests : IDisposable
{
    private readonly NotificationService _sut = new();

    public void Dispose()
    {
        // Drain the static queue so tests don't leak state
        while (_sut.ReceiveNotification() != null) { }
        _sut.Dispose();
    }

    [Fact]
    public void SendNotification_EnqueuesNotification_CanBeReceived()
    {
        _sut.SendNotification("Student", "1", "John Doe", EntityOperation.CREATE, "Admin");

        var notification = _sut.ReceiveNotification();

        Assert.NotNull(notification);
        Assert.Equal("Student", notification.EntityType);
        Assert.Equal("1", notification.EntityId);
        Assert.Equal("CREATE", notification.Operation);
        Assert.Equal("Admin", notification.CreatedBy);
        Assert.False(notification.IsRead);
    }

    [Theory]
    [InlineData(EntityOperation.CREATE, "New Student 'John Doe' has been created")]
    [InlineData(EntityOperation.UPDATE, "Student 'John Doe' has been updated")]
    [InlineData(EntityOperation.DELETE, "Student 'John Doe' has been deleted")]
    public void SendNotification_WithDisplayName_GeneratesCorrectMessage(EntityOperation operation, string expectedMessage)
    {
        _sut.SendNotification("Student", "1", "John Doe", operation, "System");

        var notification = _sut.ReceiveNotification();

        Assert.NotNull(notification);
        Assert.Equal(expectedMessage, notification.Message);
    }

    [Theory]
    [InlineData(EntityOperation.CREATE, "New Course (ID: 42) has been created")]
    [InlineData(EntityOperation.UPDATE, "Course (ID: 42) has been updated")]
    [InlineData(EntityOperation.DELETE, "Course (ID: 42) has been deleted")]
    public void SendNotification_WithoutDisplayName_UsesIdInMessage(EntityOperation operation, string expectedMessage)
    {
        _sut.SendNotification("Course", "42", operation, "System");

        var notification = _sut.ReceiveNotification();

        Assert.NotNull(notification);
        Assert.Equal(expectedMessage, notification.Message);
    }

    [Fact]
    public void SendNotification_WithNullUserName_DefaultsToSystem()
    {
        _sut.SendNotification("Student", "1", EntityOperation.CREATE);

        var notification = _sut.ReceiveNotification();

        Assert.NotNull(notification);
        Assert.Equal("System", notification.CreatedBy);
    }

    [Fact]
    public void ReceiveNotification_WhenEmpty_ReturnsNull()
    {
        // Drain any existing
        while (_sut.ReceiveNotification() != null) { }

        var result = _sut.ReceiveNotification();

        Assert.Null(result);
    }

    [Fact]
    public void SendAndReceive_MultipleNotifications_ReturnedInFifoOrder()
    {
        _sut.SendNotification("Student", "1", EntityOperation.CREATE);
        _sut.SendNotification("Course", "2", EntityOperation.UPDATE);
        _sut.SendNotification("Department", "3", EntityOperation.DELETE);

        var n1 = _sut.ReceiveNotification();
        var n2 = _sut.ReceiveNotification();
        var n3 = _sut.ReceiveNotification();

        Assert.Equal("Student", n1!.EntityType);
        Assert.Equal("Course", n2!.EntityType);
        Assert.Equal("Department", n3!.EntityType);
    }

    [Fact]
    public void MarkAsRead_DoesNotThrow()
    {
        // MarkAsRead is a no-op in the in-memory implementation
        var exception = Record.Exception(() => _sut.MarkAsRead(999));
        Assert.Null(exception);
    }

    [Fact]
    public void SendNotification_SetsCreatedAtToRecentTime()
    {
        var before = DateTime.Now.AddSeconds(-1);
        _sut.SendNotification("Student", "1", "Test", EntityOperation.CREATE, "User");
        var after = DateTime.Now.AddSeconds(1);

        var notification = _sut.ReceiveNotification();

        Assert.NotNull(notification);
        Assert.InRange(notification.CreatedAt, before, after);
    }

    [Fact]
    public void SendNotification_WithBlankDisplayName_UsesIdFallback()
    {
        _sut.SendNotification("Student", "5", "   ", EntityOperation.CREATE, "User");

        var notification = _sut.ReceiveNotification();

        Assert.NotNull(notification);
        Assert.Contains("ID: 5", notification.Message);
    }
}

namespace ContosoUniversity.Tests;

public class PaginatedListTests
{
    [Fact]
    public void Create_FirstPage_ReturnsCorrectItems()
    {
        var source = Enumerable.Range(1, 25).AsQueryable();

        var result = PaginatedList<int>.Create(source, pageIndex: 1, pageSize: 10);

        Assert.Equal(10, result.Count);
        Assert.Equal(1, result.First());
        Assert.Equal(10, result.Last());
        Assert.Equal(1, result.PageIndex);
        Assert.Equal(3, result.TotalPages);
    }

    [Fact]
    public void Create_MiddlePage_ReturnsCorrectItems()
    {
        var source = Enumerable.Range(1, 25).AsQueryable();

        var result = PaginatedList<int>.Create(source, pageIndex: 2, pageSize: 10);

        Assert.Equal(10, result.Count);
        Assert.Equal(11, result.First());
        Assert.Equal(20, result.Last());
    }

    [Fact]
    public void Create_LastPage_ReturnsRemainingItems()
    {
        var source = Enumerable.Range(1, 25).AsQueryable();

        var result = PaginatedList<int>.Create(source, pageIndex: 3, pageSize: 10);

        Assert.Equal(5, result.Count);
        Assert.Equal(21, result.First());
        Assert.Equal(25, result.Last());
    }

    [Fact]
    public void HasPreviousPage_OnFirstPage_ReturnsFalse()
    {
        var source = Enumerable.Range(1, 20).AsQueryable();

        var result = PaginatedList<int>.Create(source, pageIndex: 1, pageSize: 10);

        Assert.False(result.HasPreviousPage);
    }

    [Fact]
    public void HasPreviousPage_OnSecondPage_ReturnsTrue()
    {
        var source = Enumerable.Range(1, 20).AsQueryable();

        var result = PaginatedList<int>.Create(source, pageIndex: 2, pageSize: 10);

        Assert.True(result.HasPreviousPage);
    }

    [Fact]
    public void HasNextPage_OnLastPage_ReturnsFalse()
    {
        var source = Enumerable.Range(1, 20).AsQueryable();

        var result = PaginatedList<int>.Create(source, pageIndex: 2, pageSize: 10);

        Assert.False(result.HasNextPage);
    }

    [Fact]
    public void HasNextPage_OnFirstPage_ReturnsTrue()
    {
        var source = Enumerable.Range(1, 20).AsQueryable();

        var result = PaginatedList<int>.Create(source, pageIndex: 1, pageSize: 10);

        Assert.True(result.HasNextPage);
    }

    [Fact]
    public void Create_EmptySource_ReturnsEmptyList()
    {
        var source = Enumerable.Empty<int>().AsQueryable();

        var result = PaginatedList<int>.Create(source, pageIndex: 1, pageSize: 10);

        Assert.Empty(result);
        Assert.Equal(0, result.TotalPages);
        Assert.False(result.HasPreviousPage);
        Assert.False(result.HasNextPage);
    }

    [Fact]
    public void TotalPages_ExactMultiple_CalculatesCorrectly()
    {
        var source = Enumerable.Range(1, 30).AsQueryable();

        var result = PaginatedList<int>.Create(source, pageIndex: 1, pageSize: 10);

        Assert.Equal(3, result.TotalPages);
    }

    [Fact]
    public void TotalPages_SingleItem_IsOne()
    {
        var source = new[] { 42 }.AsQueryable();

        var result = PaginatedList<int>.Create(source, pageIndex: 1, pageSize: 10);

        Assert.Single(result);
        Assert.Equal(1, result.TotalPages);
    }
}

