    private Instructor SeedInstructor(string first = "Kim", string last = "Abercrombie",
        DateTime? hireDate = null, string? officeLocation = null)
    {
        var instructor = new Instructor
        {
            FirstMidName = first,
            LastName = last,
            HireDate = hireDate ?? new DateTime(2000, 1, 1),
            CourseAssignments = new List<CourseAssignment>()
        };
        if (officeLocation != null)
        {
            instructor.OfficeAssignment = new OfficeAssignment { Location = officeLocation };
        }
        _context.Instructors.Add(instructor);
        _context.SaveChanges();
        return instructor;
    }

    private Course SeedCourse(int courseId, string title = "Test Course")
    {
        var dept = new Department
        {
            Name = "TestDept",
            Budget = 100000,
            StartDate = new DateTime(2020, 1, 1)
        };
        _context.Departments.Add(dept);
        _context.SaveChanges();

        var course = new Course
        {
            CourseID = courseId,
            Title = title,
            Credits = 3,
            DepartmentID = dept.DepartmentID,
            Enrollments = new List<Enrollment>()
        };
        _context.Courses.Add(course);
        _context.SaveChanges();
        return course;
    }

    #region Index

    [Fact]
    public void Index_NoParams_ReturnsViewWithInstructors()
    {
        SeedInstructor("Alice", "Adams");
        SeedInstructor("Bob", "Brown");

        var result = _controller.Index(null, null) as ViewResult;

        Assert.NotNull(result);
        var model = Assert.IsType<InstructorIndexData>(result.Model);
        Assert.Equal(2, model.Instructors.Count());
    }

    [Fact]
    public void Index_InstructorsOrderedByLastName()
    {
        SeedInstructor("Bob", "Zebra");
        SeedInstructor("Alice", "Alpha");

        var result = _controller.Index(null, null) as ViewResult;

        var model = Assert.IsType<InstructorIndexData>(result!.Model);
        var instructors = model.Instructors.ToList();
        Assert.Equal("Alpha", instructors[0].LastName);
        Assert.Equal("Zebra", instructors[1].LastName);
    }

    [Fact]
    public void Index_WithInstructorId_PopulatesCourses()
    {
        var instructor = SeedInstructor();
        var course = SeedCourse(1050, "Chemistry");
        _context.CourseAssignments.Add(new CourseAssignment
        {
            InstructorID = instructor.ID,
            CourseID = course.CourseID
        });
