        _controller = new NotificationsController(_context);
        TestHelper.SetupControllerContext(_controller);
        // Drain any leftover notifications from other tests
        DrainNotifications();
    }

    public void Dispose()
    {
        DrainNotifications();
        _controller.Dispose();
        _context.Dispose();
    }

    private void DrainNotifications()
    {
        using var svc = new NotificationService();
        while (svc.ReceiveNotification() != null) { }
    }

    [Fact]
    public void Index_ReturnsView()
    {
        var result = _controller.Index();

        Assert.IsType<ViewResult>(result);
    }

