using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Tests.Helpers;
using Microsoft.AspNetCore.Hosting;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;
using Microsoft.Extensions.Logging;
using Moq;

namespace ContosoUniversity.Tests.Controllers;

public class CoursesControllerTests : IDisposable
{
    private readonly SchoolContext _context;
    private readonly CoursesController _controller;
    private readonly Mock<IWebHostEnvironment> _mockEnv;
    private readonly Mock<ILogger<CoursesController>> _mockLogger;
    private readonly string _tempDir;

    public CoursesControllerTests()
    {
        _context = TestHelper.CreateInMemoryContext();
        _mockEnv = new Mock<IWebHostEnvironment>();
        _mockLogger = new Mock<ILogger<CoursesController>>();
        _tempDir = Path.Combine(Path.GetTempPath(), Guid.NewGuid().ToString());
        Directory.CreateDirectory(_tempDir);
        _mockEnv.Setup(e => e.WebRootPath).Returns(_tempDir);
        _mockEnv.Setup(e => e.ContentRootPath).Returns(_tempDir);
        _controller = new CoursesController(_context, _mockEnv.Object, _mockLogger.Object);
        TestHelper.SetupControllerContext(_controller);
    }

    public void Dispose()
    {
        _controller.Dispose();
        _context.Dispose();
        if (Directory.Exists(_tempDir))
            Directory.Delete(_tempDir, true);
    }

    private Department SeedDepartment(string name = "Engineering")
    {
        var dept = new Department
        {
            Name = name,
            Budget = 100000,
            StartDate = new DateTime(2020, 1, 1)
        };
        _context.Departments.Add(dept);
        _context.SaveChanges();
        return dept;
    }

    private Course SeedCourse(int courseId = 1050, string title = "Chemistry", int credits = 3, int? departmentId = null)
    {
        if (departmentId == null)
        {
            var dept = SeedDepartment();
            departmentId = dept.DepartmentID;
        }
        var course = new Course
        {
            CourseID = courseId,
            Title = title,
            Credits = credits,
            DepartmentID = departmentId.Value
        };
        _context.Courses.Add(course);
        _context.SaveChanges();
        return course;
    }

    #region Index

    [Fact]
    public void Index_ReturnsViewWithAllCourses()
    {
        var dept = SeedDepartment();
        SeedCourse(1050, "Chemistry", 3, dept.DepartmentID);
        SeedCourse(2021, "Composition", 3, dept.DepartmentID);

        var result = _controller.Index() as ViewResult;

        Assert.NotNull(result);
        var model = Assert.IsType<List<Course>>(result.Model);
        Assert.Equal(2, model.Count);
    }

    #endregion

    #region Details

    [Fact]
    public void Details_NullId_ReturnsBadRequest()
    {
        var result = _controller.Details(null);

        var statusResult = Assert.IsType<StatusCodeResult>(result);
        Assert.Equal(400, statusResult.StatusCode);
    }

    [Fact]
    public void Details_ValidId_ReturnsViewWithCourse()
    {
        var course = SeedCourse();

        var result = _controller.Details(course.CourseID) as ViewResult;

        Assert.NotNull(result);
        var model = Assert.IsType<Course>(result.Model);
        Assert.Equal(course.CourseID, model.CourseID);
        Assert.Equal("Chemistry", model.Title);
    }

    #endregion

    #region Create GET

    [Fact]
    public void Create_Get_ReturnsViewWithDepartmentSelectList()
    {
        SeedDepartment("Mathematics");

        var result = _controller.Create() as ViewResult;

        Assert.NotNull(result);
        Assert.NotNull(_controller.ViewBag.DepartmentID);
    }

    #endregion

    #region Create POST

    [Fact]
    public void Create_Post_ValidCourse_NoImage_RedirectsToIndex()
    {
        var dept = SeedDepartment();
        var course = new Course
        {
            CourseID = 5000,
            Title = "New Course",
            Credits = 3,
            DepartmentID = dept.DepartmentID
        };

        var result = _controller.Create(course, null!);

        var redirect = Assert.IsType<RedirectToActionResult>(result);
        Assert.Equal("Index", redirect.ActionName);
        Assert.Single(_context.Courses);
    }

    [Fact]
    public void Create_Post_InvalidModelState_ReturnsView()
    {
        var dept = SeedDepartment();
        _controller.ModelState.AddModelError("Title", "Required");
        var course = new Course { CourseID = 5000, DepartmentID = dept.DepartmentID };

        var result = _controller.Create(course, null!) as ViewResult;

        Assert.NotNull(result);
        Assert.Empty(_context.Courses);
    }

    [Fact]
    public void Create_Post_InvalidImageExtension_ReturnsViewWithError()
    {
        var dept = SeedDepartment();
        var course = new Course
        {
            CourseID = 5000,
            Title = "Course",
            Credits = 3,
            DepartmentID = dept.DepartmentID
        };
        var mockFile = CreateMockFormFile("test.exe", 1024);

        var result = _controller.Create(course, mockFile) as ViewResult;

        Assert.NotNull(result);
        Assert.True(_controller.ModelState.ContainsKey("teachingMaterialImage"));
    }

    [Fact]
    public void Create_Post_OversizedImage_ReturnsViewWithError()
    {
        var dept = SeedDepartment();
        var course = new Course
        {
            CourseID = 5000,
            Title = "Course",
            Credits = 3,
            DepartmentID = dept.DepartmentID
        };
        var mockFile = CreateMockFormFile("test.jpg", 6 * 1024 * 1024); // 6MB

        var result = _controller.Create(course, mockFile) as ViewResult;

        Assert.NotNull(result);
        Assert.True(_controller.ModelState.ContainsKey("teachingMaterialImage"));
        var errors = _controller.ModelState["teachingMaterialImage"]!.Errors;
        Assert.Contains(errors, e => e.ErrorMessage.Contains("5MB"));
    }

    [Fact]
    public void Create_Post_ValidImage_SavesFileAndRedirects()
    {
        var dept = SeedDepartment();
        var course = new Course
        {
            CourseID = 5000,
            Title = "Course With Image",
            Credits = 3,
            DepartmentID = dept.DepartmentID
        };
        var mockFile = CreateMockFormFile("photo.png", 1024);

        var result = _controller.Create(course, mockFile);

        var redirect = Assert.IsType<RedirectToActionResult>(result);
        Assert.Equal("Index", redirect.ActionName);
        var savedCourse = _context.Courses.Find(5000);
        Assert.NotNull(savedCourse);
        Assert.StartsWith("/Uploads/TeachingMaterials/", savedCourse.TeachingMaterialImagePath);
    }

    #endregion

    #region Edit GET

    [Fact]
    public void Edit_Get_NullId_ReturnsBadRequest()
    {
        var result = _controller.Edit(null);

        var statusResult = Assert.IsType<StatusCodeResult>(result);
        Assert.Equal(400, statusResult.StatusCode);
    }

    [Fact]
    public void Edit_Get_InvalidId_ReturnsNotFound()
    {
        var result = _controller.Edit(9999);

        Assert.IsType<NotFoundResult>(result);
    }

    [Fact]
    public void Edit_Get_ValidId_ReturnsViewWithCourse()
    {
        var course = SeedCourse();

        var result = _controller.Edit(course.CourseID) as ViewResult;

        Assert.NotNull(result);
        var model = Assert.IsType<Course>(result.Model);
        Assert.Equal(course.CourseID, model.CourseID);
    }

    #endregion

    #region Edit POST

    [Fact]
    public void Edit_Post_ValidCourse_NoImage_RedirectsToIndex()
    {
        var course = SeedCourse();
        _context.Entry(course).State = Microsoft.EntityFrameworkCore.EntityState.Detached;

        var updatedCourse = new Course
        {
            CourseID = course.CourseID,
            Title = "Updated Title",
            Credits = 4,
            DepartmentID = course.DepartmentID
        };

        var result = _controller.Edit(updatedCourse, null!);

        var redirect = Assert.IsType<RedirectToActionResult>(result);
        Assert.Equal("Index", redirect.ActionName);
    }

    [Fact]
    public void Edit_Post_InvalidExtension_ReturnsViewWithError()
    {
        var course = SeedCourse();
        _context.Entry(course).State = Microsoft.EntityFrameworkCore.EntityState.Detached;

        var editCourse = new Course
        {
            CourseID = course.CourseID,
            Title = "Updated",
            Credits = 3,
            DepartmentID = course.DepartmentID
        };
        var mockFile = CreateMockFormFile("malware.pdf", 1024);

        var result = _controller.Edit(editCourse, mockFile) as ViewResult;

        Assert.NotNull(result);
        Assert.True(_controller.ModelState.ContainsKey("teachingMaterialImage"));
    }

    #endregion

    #region Delete GET

    [Fact]
    public void Delete_Get_NullId_ReturnsBadRequest()
    {
        var result = _controller.Delete(null);

        var statusResult = Assert.IsType<StatusCodeResult>(result);
        Assert.Equal(400, statusResult.StatusCode);
    }

    [Fact]
    public void Delete_Get_ValidId_ReturnsViewWithCourse()
    {
        var course = SeedCourse();

        var result = _controller.Delete(course.CourseID) as ViewResult;

        Assert.NotNull(result);
        var model = Assert.IsType<Course>(result.Model);
        Assert.Equal(course.CourseID, model.CourseID);
    }

    #endregion

    #region DeleteConfirmed

    [Fact]
    public void DeleteConfirmed_ValidId_RemovesCourseAndRedirects()
    {
        var course = SeedCourse();

        var result = _controller.DeleteConfirmed(course.CourseID);

        var redirect = Assert.IsType<RedirectToActionResult>(result);
        Assert.Equal("Index", redirect.ActionName);
        Assert.Empty(_context.Courses);
    }

    #endregion

    private static IFormFile CreateMockFormFile(string fileName, long length)
    {
        var mock = new Mock<IFormFile>();
        var content = new byte[Math.Min(length, 1024)];
        var stream = new MemoryStream(content);
        mock.Setup(f => f.FileName).Returns(fileName);
        mock.Setup(f => f.Length).Returns(length);
        mock.Setup(f => f.OpenReadStream()).Returns(stream);
        mock.Setup(f => f.CopyTo(It.IsAny<Stream>())).Callback<Stream>(s => stream.CopyTo(s));
        return mock.Object;
    }
}

